using Test
using Advectra
import Advectra: build_operator

# Exact solution of ∂n/∂t = ν∇²n: n̂(t) = n̂(0)exp(-νk²t)
function exact_diffusion(n0, domain, ν, t)
    laplacian = build_operator(Val(:laplacian), domain)
    bwd_plan(domain) * ((fwd_plan(domain) * n0) .* exp.(ν .* laplacian.coeffs .* t))
end

function solve_diffusion(domain, u0, NonLinear; physical_transform=identity)
    Linear(du, u, operators, p, t) = du .= p.ν * operators.laplacian(u)
    diagnostics = @diagnostics [progress(; stride=10), sample_density(; stride=10)]
    prob = SpectralODEProblem(Linear, NonLinear, u0, domain, [0.0, 2.0]; p=(ν=0.5,),
                              dt=1e-3, diagnostics=diagnostics, operators=:all)
    output = Output(prob; filename=joinpath(mktempdir(), "diffusion.h5"),
                    physical_transform=physical_transform)
    sol = spectral_solve(prob, MSS3(), output; debug=true)
    return sol.simulation["Density/data"][:, :, end], sol.simulation["Density/t"][end]
end

# ∂η/∂t = ν(∇²η + |∇η|²) with η = log(n) is ∂n/∂t = ν∇²n written for the logarithm
function LogNonLinear(du, u, operators, p, t)
    @unpack diff_x, diff_y, quadratic_term = operators
    @unpack ν = p
    du .= ν * (quadratic_term(diff_x(u), diff_x(u)) .+ quadratic_term(diff_y(u), diff_y(u)))
end

# log_gaussian stores log(1 + n), so this recovers n
inverse_transform!(U) = @views U[:, :, 1] .= exp.(U[:, :, 1]) .- 1

# Nx ≠ Ny and Lx ≠ Ly to catch mixed up axes
const domain = Domain(32, 16; Lx=20, Ly=12)

@testset "Integration Test: Linear Diffusion" begin
    n0 = initial_condition(gaussian, domain)
    final_data, t = solve_diffusion(domain, n0, (du, u, operators, p, t) -> du .= 0)

    @test t ≈ 2.0
    @test final_data ≈ exact_diffusion(n0, domain, 0.5, t) atol = 1e-6
end

@testset "Integration Test: Non-linear Diffusion" begin
    final_data, t = solve_diffusion(domain, initial_condition(log_gaussian, domain),
                                    LogNonLinear; physical_transform=inverse_transform!)

    @test t ≈ 2.0
    n0 = initial_condition(gaussian, domain)
    @test final_data ≈ exact_diffusion(n0, domain, 0.5, t) atol = 1e-5
end

